/// <reference types="vite/client" />

/**
 * Routes generated by `vite-plugin-pages` from every file in `src/pages`.
 * `importMode` defaults to async, so pages are lazily code-split.
 */
declare module "virtual:generated-pages-react" {
  import type { RouteObject } from "react-router-dom";
  const routes: RouteObject[];
  export default routes;
}

declare module "~react-pages" {
  import type { RouteObject } from "react-router-dom";
  const routes: RouteObject[];
  export default routes;
}

/**
 * The View Transitions API is used for the circular theme reveal.
 * It is still optional in TypeScript's DOM lib, so we describe it here.
 */
interface ViewTransition {
  finished: Promise<void>;
  ready: Promise<void>;
  updateCallbackDone: Promise<void>;
}

interface Document {
  startViewTransition?: (callback: () => void | Promise<void>) => ViewTransition;
}
